def edit_token_for(slug: str) -> str:
    """Same derivation as the app: HMAC of the slug under CRON_SECRET_TOKEN."""
    import hashlib, hmac
    secret = None
    app_env = Path.home() / "Desktop" / "Linkedin_content_fatory" / ".env.local"
    if app_env.exists():
        for line in app_env.read_text().splitlines():
            if line.strip().startswith("CRON_SECRET_TOKEN="):
                secret = line.split("=", 1)[1].strip().strip('"').strip("'")
    if not secret:
        return ""
    return hmac.new(secret.encode(), f"preview-edit:{slug}".encode(),
                    hashlib.sha256).hexdigest()[:24]


def check_for_unpulled_edits(preview_slug: str, posts: list) -> list:
    """Return [(index, post_slug)] for live posts that were edited in the UI and whose text
    no longer matches the draft file we are about to push."""
    token = edit_token_for(preview_slug)
    if not token:
        return []
    try:
        req = urllib.request.Request(
            PP_URL.replace("/api/public/perfect-preview", "/api/public-preview"),
            data=json.dumps({"slug": preview_slug, "token": token}).encode(),
            headers={"Content-Type": "application/json"}, method="POST")
        with urllib.request.urlopen(req, context=SSL_CTX, timeout=90) as r:
            live = json.loads(r.read().decode()).get("data", {}).get("posts") or []
    except Exception:
        return []  # never block a push because the check itself failed

    by_slug = {p.get("post_slug"): p for p in live if isinstance(p, dict) and p.get("post_slug")}
    out = []
    for i, post in enumerate(posts):
        prior = by_slug.get(post.get("slug")) or (live[i] if i < len(live) else None)
        if not isinstance(prior, dict):
            continue
        if (prior.get("edit_history") and
                (prior.get("content") or "").strip() != post["content"].strip()):
            out.append((i, post.get("slug") or f"post {i + 1}"))
    return out


def strip_frontmatter(text: str) -> str:
    if not text.startswith("---"):
        return text
    parts = text.split("---", 2)
    return parts[2].lstrip("\n") if len(parts) >= 3 else text

